        {"\\(", "<ul>"},
        {"\\)", "</ul>"},
        {"- ", "<li>"},
        {"\\[ ", "<img src=''>"},
        {"](", ")</img>"},
        {"\\( ", "<blockquote>"},
        {"\\)", "</blockquote>"}
    };

