// Function to check if a point collides with the snake
int collidesWithSnake(int x, int y) {
    for (int I = 1; I < snake.length; i++) {
        if (snake.body[i].x == x && snake.body[i].y == y) {
            return 1;
        }
    }
    return 0;
}

// Main game loop
while (true) {
    // Move snake
    for (int I = snake.length - 1; I > 0; i--) {
        snake.body[i].x = snake.body[i - 1].x;
        snake.body[i].y = snake.body[i - 1].y;
    }

    switch (snake.direction) {
        case 0: // Right
            snake.body[0].x += 20;
            break;
        case 1: // Down
            snake.body[0].y += 20;
            break;
        case 2: // Left
            snake.body[0].x -= 20;
            break;
        case 3: // Up
            snake.body[0].y -= 20;
            break;
