```cpp
#include <iostream>
#include <fstream>
#include <string>

using namespace std;

int main() {
    string fileName;
    string searchWord;
    int count = 0;

    // Get file name and search word from user input
    cout << "Enter the file name: ";
    getline(cin, fileName);

    cout << "Enter the search word: ";
    getline(cin, searchWord);

    // Open file and read line by line
    ifstream file(fileName);
    if (!file.is_open()) {
        cerr << "Error opening file: " << fileName << endl;
        return 1;
    }

    string line;
    while (getline(file, line)) {
        size_t pos = 0;
        while ((pos = line.find(searchWord, pos)) != string::npos) {
            count++;
            pos += searchWord.length();
        }
    }

    file.close();

    // Display search results
    cout << "The word \"" << searchWord << "\" appears " << count << " times in the file " << fileName << "." << endl;

    return 0;
}
```

En este ejemplo, primero se solicitan el nombre del archivo y la palabra a buscar al usuario. Luego se abre el archivo y se lee línea por línea utilizando la función `getline()` de la biblioteca de flujo de entrada/salida de C++. Para contar las apariciones de la palabra buscada, se utiliza la función `find()` de la clase `string` para buscar la posición de la primera ocurrencia de la palabra en la línea actual. El bucle `while` se repite hasta que no haya más apariciones de la palabra en la línea actual. Finalmente, se cierra el archivo y se muestran los resultados de la búsqueda al usuario.

